// 回溯：逐列放皇后，用三個集合記錄被佔用的欄與兩條對角線
// 時間複雜度: O(n!)，空間複雜度: O(n)
function solveNQueens(n) {
    const result = [];
    const queens = []; // queens[row] = 該列皇后所在欄
    const cols = new Set(), diag1 = new Set(), diag2 = new Set();
    const backtrack = (row) => {
        if (row === n) {
            result.push(queens.map(c => '.'.repeat(c) + 'Q' + '.'.repeat(n - c - 1)));
            return;
        }
        for (let c = 0; c < n; c++) {
            if (cols.has(c) || diag1.has(row - c) || diag2.has(row + c))
                continue;
            queens.push(c);
            cols.add(c);
            diag1.add(row - c);
            diag2.add(row + c);
            backtrack(row + 1);
            queens.pop();
            cols.delete(c);
            diag1.delete(row - c);
            diag2.delete(row + c);
        }
    };
    backtrack(0);
    return result;
}

